-- Approved 12 October 2026. Additive catalogue and rules only: no historic snapshots or UBL budgets updated.
CREATE TABLE inventory_catalogue_versions (
 item_id text NOT NULL,version integer NOT NULL CHECK(version>0),payload jsonb NOT NULL,
 rate_key text REFERENCES item_master(key),created_at timestamptz NOT NULL DEFAULT now(),
 PRIMARY KEY(item_id,version)
);
CREATE VIEW inventory_catalogue_current AS SELECT DISTINCT ON(item_id) * FROM inventory_catalogue_versions ORDER BY item_id,version DESC;
CREATE TABLE inventory_item_aliases (alias text PRIMARY KEY,item_id text NOT NULL);
CREATE TABLE engineering_profile_versions (
 key text NOT NULL,version integer NOT NULL,payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(key,version)
);
CREATE VIEW engineering_profiles_current AS SELECT DISTINCT ON(key) * FROM engineering_profile_versions ORDER BY key,version DESC;
CREATE TABLE customer_order_reference_history (key text PRIMARY KEY,payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TRIGGER immutable_inventory_catalogue BEFORE UPDATE OR DELETE ON inventory_catalogue_versions FOR EACH ROW EXECUTE FUNCTION prevent_master_version_mutation();
CREATE TRIGGER immutable_engineering_profiles BEFORE UPDATE OR DELETE ON engineering_profile_versions FOR EACH ROW EXECUTE FUNCTION prevent_master_version_mutation();



-- Future standard calculations use one site-level enclosure package; retain earlier rule versions.
SELECT key,version+1,rule_group,setting,1,'Abu Bakar approved site-level AC/DC enclosure package, 12 October 2026'
FROM (SELECT * FROM rule_versions WHERE key='engineering-20' ORDER BY version DESC LIMIT 1) r WHERE value<>1;
